const tenantMiddleware = (pool: Pool) => async (req: Request, res: Response, next: NextFunction) => {
  const tenantId = req.header('X-Tenant-ID');
  if (!tenantId || !/^tenant_\d+$/.test(tenantId)) {
    return res.status(403).json({ error: 'Invalid tenant ID' });
